def tc(module, sub, description, dependencies, steps, expected, priority="HIGH", data="<TEST_DATA>",
       status="NOT TESTED", actual="Not Executed", ready="YES", functional="X", sit="", perf="", defect="", remarks=""):
    return [module, sub, description, dependencies, ready, functional, sit, perf, steps, expected,
            actual, status, priority, data, defect, remarks]

