def style_sheet(ws, widths):
    header_fill = PatternFill("solid", fgColor="1F4E78")
    thin = Side(style="thin", color="D9E2F3")
    for cell in ws[1]:
        cell.font = Font(color="FFFFFF", bold=True)
        cell.fill = header_fill
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        cell.border = Border(bottom=thin)
    ws.freeze_panes = "A2"
    ws.auto_filter.ref = ws.dimensions
    for i, width in enumerate(widths, 1): ws.column_dimensions[get_column_letter(i)].width = width
    for row in ws.iter_rows(min_row=2):
        for cell in row:
            cell.alignment = Alignment(vertical="top", wrap_text=True)
            cell.border = Border(bottom=thin)

def main():
    wb = Workbook()
    ws = wb.active; ws.title = "Test Cases"; ws.append(HEADERS)
    for i, row in enumerate(CASES, 1): ws.append([f"TC{i:03d}"] + row)
    style_sheet(ws, [13,18,20,42,34,15,12,10,14,48,42,48,24,12,26,13,48])
    for r in range(2, ws.max_row + 1): ws.row_dimensions[r].height = 70
    status_dv = DataValidation(type="list", formula1='"PASS,FAIL,BLOCKED,NOT TESTED,NOT IMPLEMENTED,PARTIALLY IMPLEMENTED"'); ws.add_data_validation(status_dv); status_dv.add(f"M2:M{ws.max_row}")
    priority_dv = DataValidation(type="list", formula1='"CRITICAL,HIGH,MEDIUM,LOW"'); ws.add_data_validation(priority_dv); priority_dv.add(f"N2:N{ws.max_row}")
    ready_dv = DataValidation(type="list", formula1='"YES,NO,BLOCKED"'); ws.add_data_validation(ready_dv); ready_dv.add(f"F2:F{ws.max_row}")
    colors = {"PASS":"C6EFCE", "FAIL":"FFC7CE", "BLOCKED":"FFEB9C", "NOT TESTED":"D9EAF7", "NOT IMPLEMENTED":"D9D9D9", "PARTIALLY IMPLEMENTED":"FCE4D6"}
    for value, color in colors.items(): ws.conditional_formatting.add(f"M2:M{ws.max_row}", CellIsRule(operator="equal", formula=[f'"{value}"'], fill=PatternFill("solid", fgColor=color)))

    summary = wb.create_sheet("Test Summary"); summary.append(["Metric", "Value"])
    metrics = [("Total Test Cases", f"=COUNTA('Test Cases'!A2:A{ws.max_row})"), ("PASS", "=COUNTIF('Test Cases'!M:M,\"PASS\")"), ("FAIL", "=COUNTIF('Test Cases'!M:M,\"FAIL\")"), ("BLOCKED", "=COUNTIF('Test Cases'!M:M,\"BLOCKED\")"), ("NOT TESTED", "=COUNTIF('Test Cases'!M:M,\"NOT TESTED\")"), ("NOT IMPLEMENTED", "=COUNTIF('Test Cases'!M:M,\"NOT IMPLEMENTED\")"), ("PARTIALLY IMPLEMENTED", "=COUNTIF('Test Cases'!M:M,\"PARTIALLY IMPLEMENTED\")"), ("Functional Tests", "=COUNTIF('Test Cases'!G:G,\"X\")"), ("SIT Tests", "=COUNTIF('Test Cases'!H:H,\"X\")"), ("Performance Tests", "=COUNTIF('Test Cases'!I:I,\"X\")"), ("Pass %", "=IFERROR(B3/B2,0)"), ("Fail %", "=IFERROR(B4/B2,0)"), ("Execution %", "=IFERROR((B3+B4)/B2,0)")]
    for row in metrics: summary.append(row)
    style_sheet(summary, [28,24]); [setattr(summary[f"B{r}"], "number_format", "0.00%") for r in (12,13,14)]

    coverage = wb.create_sheet("Module Coverage"); coverage.append(["Module", "Total Test Cases", "Implemented", "Tested", "Passed", "Failed", "Blocked", "Not Implemented", "Coverage %"])
    modules = sorted({r[0] for r in CASES})
    for idx, module in enumerate(modules, 2):
        coverage.append([module, f'=COUNTIF(\'Test Cases\'!B:B,A{idx})', f'=B{idx}-COUNTIFS(\'Test Cases\'!B:B,A{idx},\'Test Cases\'!M:M,"NOT IMPLEMENTED")', f'=COUNTIFS(\'Test Cases\'!B:B,A{idx},\'Test Cases\'!M:M,"PASS")+COUNTIFS(\'Test Cases\'!B:B,A{idx},\'Test Cases\'!M:M,"FAIL")+COUNTIFS(\'Test Cases\'!B:B,A{idx},\'Test Cases\'!M:M,"BLOCKED")', f'=COUNTIFS(\'Test Cases\'!B:B,A{idx},\'Test Cases\'!M:M,"PASS")', f'=COUNTIFS(\'Test Cases\'!B:B,A{idx},\'Test Cases\'!M:M,"FAIL")', f'=COUNTIFS(\'Test Cases\'!B:B,A{idx},\'Test Cases\'!M:M,"BLOCKED")', f'=COUNTIFS(\'Test Cases\'!B:B,A{idx},\'Test Cases\'!M:M,"NOT IMPLEMENTED")', f'=IFERROR(D{idx}/B{idx},0)'])
    style_sheet(coverage, [28,18,16,14,14,14,14,20,16])
    for cell in coverage["I"][1:]: cell.number_format = "0.00%"

    how = wb.create_sheet("How To Use"); how.append(["Column", "Usage"])
    uses = [("Test Case ID", "Unique, stable identifier."), ("Module / Sub Module", "Repository-derived functional area."), ("Test Case Description", "What the test verifies."), ("Preconditions / Dependencies", "Environment, account, data, and service requirements."), ("TC Ready for Testing", "YES = runnable; NO = not implemented; BLOCKED = dependency unavailable."), ("Functional / SIT / Performance", "X identifies behavior, integration, or an actual performance scenario."), ("Test Steps", "Execute in order and preserve evidence."), ("Expected Result", "Observable product behavior or status code based on the implementation."), ("Actual Result", "Observed output; Not Executed means no runtime claim."), ("Status", "Only PASS, FAIL, BLOCKED, NOT TESTED, NOT IMPLEMENTED, PARTIALLY IMPLEMENTED."), ("Priority", "CRITICAL/HIGH/MEDIUM/LOW risk priority."), ("Test Data", "Use placeholders only; never record secrets."), ("Defect ID", "BUG reference for identified issues."), ("Remarks", "Actual route/file traceability and constraints.")]
    for row in uses: how.append(row)
    style_sheet(how, [32,110])

    current = wb.create_sheet("Current Status"); current.append(["Module", "Implementation Status", "Testing Status", "Known Issue", "Severity", "Priority", "Affected File", "Recommendation"])
    for row in ISSUES: current.append(row)
    style_sheet(current, [24,24,20,58,12,12,58,65])
    for r in range(2, current.max_row + 1): current.row_dimensions[r].height = 65

    wb.save(OUT)
    # Re-open ensures the produced OOXML archive is readable and all mandatory sheets exist.
    check = load_workbook(OUT, data_only=False)
    assert check.sheetnames == ["Test Cases", "Test Summary", "Module Coverage", "How To Use", "Current Status"]
    assert len({c.value for c in check["Test Cases"]["A"][1:]}) == len(CASES)
    assert not any("PASSWORD@" in str(cell.value).upper() for sh in check for row in sh.iter_rows() for cell in row)
    print(f"Created {OUT} with {len(CASES)} test cases.")

if __name__ == "__main__": main()
